SELECT `__typedhouse_input`.`tenantId`, `__typedhouse_input`.`entityId`, `__typedhouse_input`.`category`, `__typedhouse_input`.`state`, `__typedhouse_input`.`part_specifications`, `__typedhouse_input`.`matched_part_ids`, `__typedhouse_input`.`countOfParts`, `__typedhouse_input`.`updatedAt` FROM (SELECT `tenantId`, `entityId`, `category`, `state`, `part_specifications`, `matched_part_ids`, `countOfParts`, `updatedAt` FROM `entity_ots_component` LIMIT 2 BY `category`) AS `__typedhouse_input` LIMIT 1 BY `__typedhouse_input`.`state`
